// Des: Unit tests for link chaining and supervisor
// Flo: parse link specs > match fake completions > assert ring, backoff, ownership
// I/O: fake specs, done records, ids > pass or fail
// ===================================================================
const std = @import("std"); const supe = @import("ru-task-supe.zig"); const tszz = std.testing; const CF = supe.CF;
fn doneMake(iden: []const u8, okzz: bool, dept: u8) supe.Done { var done: supe.Done = .{ .okzz = okzz, .dept = dept }; @memcpy(done.iden[0..iden.len], iden); done.iden_leng = iden.len; return done; }
test "linkPars accepts the three documented forms" { const link_anyz = try supe.linkPars("after:build"); try tszz.expectEqualStrings("build", link_anyz.pare); try tszz.expectEqual(supe.LinkFilt.anyz, link_anyz.filt); const link_okzz = try supe.linkPars("after:build:ok"); try tszz.expectEqualStrings("build", link_okzz.pare); try tszz.expectEqual(supe.LinkFilt.okzz, link_okzz.filt); const link_fail = try supe.linkPars("after:build:fail"); try tszz.expectEqualStrings("build", link_fail.pare); try tszz.expectEqual(supe.LinkFilt.fail, link_fail.filt); const link_spac = try supe.linkPars("  after:build:ok  "); try tszz.expectEqualStrings("build", link_spac.pare); }
test "linkPars rejects a bare id and a bad filter" { try tszz.expectError(supe.LinkErro.BadPrefix, supe.linkPars("build")); try tszz.expectError(supe.LinkErro.BadPrefix, supe.linkPars("before:build")); try tszz.expectError(supe.LinkErro.NoParent, supe.linkPars("after:")); try tszz.expectError(supe.LinkErro.NoParent, supe.linkPars("after::ok")); try tszz.expectError(supe.LinkErro.BadFilter, supe.linkPars("after:build:maybe")); try tszz.expectError(supe.LinkErro.BadFilter, supe.linkPars("after:build:OK")); }
test "linkMatc honors the ok/fail filter" { const link_anyz = try supe.linkPars("after:build"); const link_okzz = try supe.linkPars("after:build:ok"); const link_fail = try supe.linkPars("after:build:fail"); const done_okzz = doneMake("build", true, 0); const done_fail = doneMake("build", false, 0); try tszz.expect(supe.linkMatc(link_anyz, &done_okzz)); try tszz.expect(supe.linkMatc(link_anyz, &done_fail)); try tszz.expect(supe.linkMatc(link_okzz, &done_okzz)); try tszz.expect(!supe.linkMatc(link_okzz, &done_fail)); try tszz.expect(!supe.linkMatc(link_fail, &done_okzz)); try tszz.expect(supe.linkMatc(link_fail, &done_fail)); }
test "linkMatc ignores a different parent" { const spec = try supe.linkPars("after:build"); const othe = doneMake("deploy", true, 0); try tszz.expect(!supe.linkMatc(spec, &othe)); }
test "linkMatc refuses to extend a chain past the depth cap" { const spec = try supe.linkPars("after:build"); const shal = doneMake("build", true, CF.maxz_casc_dept - 1); const atcp = doneMake("build", true, CF.maxz_casc_dept); const over = doneMake("build", true, CF.maxz_casc_dept + 3); try tszz.expect(supe.linkMatc(spec, &shal)); try tszz.expect(!supe.linkMatc(spec, &atcp)); try tszz.expect(!supe.linkMatc(spec, &over)); }
test "DoneRing keeps order and reports items" { var ring: supe.DoneRing = .{}; ring.push("a", true, 0); ring.push("b", false, 1); try tszz.expectEqual(@as(usize, 2), ring.item().len); try tszz.expectEqualStrings("a", ring.item()[0].name()); try tszz.expectEqualStrings("b", ring.item()[1].name()); try tszz.expect(ring.item()[0].okzz); try tszz.expect(!ring.item()[1].okzz); try tszz.expectEqual(@as(u8, 1), ring.item()[1].dept); ring.clea(); try tszz.expectEqual(@as(usize, 0), ring.item().len); }
test "DoneRing drops the OLDEST on overflow, and counts it" { var ring: supe.DoneRing = .{}; var indx: usize = 0; while (indx < CF.done_ring + 5) : (indx += 1) { var bufz: [16]u8 = undefined; const iden = std.fmt.bufPrint(&bufz, "t{d}", .{indx}) catch unreachable; ring.push(iden, true, 0); } try tszz.expectEqual(@as(usize, CF.done_ring), ring.item().len); try tszz.expectEqual(@as(u32, 5), ring.drop); try tszz.expectEqualStrings("t5", ring.item()[0].name()); var lastz: [16]u8 = undefined; const want = std.fmt.bufPrint(&lastz, "t{d}", .{CF.done_ring + 4}) catch unreachable; try tszz.expectEqualStrings(want, ring.item()[ring.item().len - 1].name()); }
test "DoneRing truncates an over-long id instead of overflowing" { var ring: supe.DoneRing = .{}; const long = "x" ** 300; ring.push(long, true, 0); try tszz.expectEqual(@as(usize, 128), ring.item()[0].name().len); }
test "backoff doubles to the cap and never overflows" { try tszz.expectEqual(@as(u32, 2000), supe.backNext(1000)); try tszz.expectEqual(@as(u32, 4000), supe.backNext(2000)); try tszz.expectEqual(@as(u32, 60_000), supe.backNext(32_000)); try tszz.expectEqual(@as(u32, 60_000), supe.backNext(60_000)); try tszz.expectEqual(@as(u32, 60_000), supe.backNext(std.math.maxInt(u32))); }
test "a run counts as healthy only past the threshold" { try tszz.expect(!supe.runzHeal(0)); try tszz.expect(!supe.runzHeal(CF.heal_runz_msec - 1)); try tszz.expect(supe.runzHeal(CF.heal_runz_msec)); try tszz.expect(supe.runzHeal(CF.heal_runz_msec * 10)); }
test "Supe crea/dest owns its strings" { const supz = try supe.Supe.crea(tszz.allocator, "srv", "node app.js", "E:\\x", .defa); defer supz.dest(); try tszz.expectEqualStrings("srv", supz.iden); try tszz.expectEqualStrings("node app.js", supz.cmdz); try tszz.expectEqualStrings("E:\\x", supz.cwdz); try tszz.expect(!supz.stop.load(.acquire)); try tszz.expectEqual(CF.back_minz_msec, supz.back_msec); }
